/** Auto-generated for round 69 */
export const QUIZ_ITEMS = [
  { id: "2265", section: "الفرائض والمواريث", category: "المواريث", level: "متوسط", question: "ما موانع الإرث الثلاثة في الفقه الإسلامي؟", answer: "ثلاثة: 1- القتل العمد العدوان (القاتل لا يرث ممن قتله). 2- اختلاف الدين (المسلم لا يرث الكافر ولا الكافر المسلم بالإجماع). 3- الرق (العبد لا يرث ولا يُورَث في حكمه).", explanation: "يُستفاد منه في باب المواريث. يُستفاد منه في باب المواريث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2266", section: "الفرائض والمواريث", category: "الفروض", level: "صعب", question: "كم فريضة حددها القرآن الكريم في المواريث؟", answer: "ستة فروض مقدّرة: النصف (1/2)، الربع (1/4)، الثمن (1/8)، الثلثان (2/3)، الثلث (1/3)، السدس (1/6) — وكل منها لمستحق محدد بآيات النساء (11-12 و176).", explanation: "يُستفاد منه في باب الفروض. يُستفاد منه في باب الفروض مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2267", section: "الفرائض والمواريث", category: "الحجب", level: "صعب", question: "ما الفرق بين حجب الحرمان وحجب النقصان؟", answer: "حجب الحرمان: حجب الوارث كلياً عن الإرث — كحجب الأخ بالابن. حجب النقصان: نقل الوارث من فرض أعلى إلى أدنى — كانتقال الزوج من النصف (1/2) إلى الربع (1/4) عند وجود الولد.", explanation: "يُستفاد منه في باب الحجب. يُستفاد منه في باب الحجب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2268", section: "الفرائض والمواريث", category: "أصحاب الفروض", level: "متوسط", question: "من الورثة الذين لا يُحجبون حجب حرمان أبداً؟", answer: "ستة: الأب، الأم، الابن، البنت، الزوج، الزوجة — لا يُحجبون حجب حرمان مطلقاً وإن نقص نصيبهم بحجب النقصان (كانتقال الزوج من النصف إلى الربع عند وجود الولد). أما ابن الابن (الحفيد) فليس منهم؛ إذ يُحجب حجب حرمان تاماً بوجود الابن.", explanation: "يُستفاد منه في باب أصحاب الفروض. يُستفاد منه في باب أصحاب الفروض مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2269", section: "الفرائض والمواريث", category: "الوصية", level: "متوسط", question: "ما أقصى ما يجوز للمسلم إيصاء به من ماله؟", answer: "لا تجوز الوصية بأكثر من ثلث المال للأجانب — لحديث سعد رضي الله عنه: «الثلث والثلث كثير» (البخاري). ولا تجوز الوصية لوارث ألبتة إلا بإجازة بقية الورثة.", explanation: "يُستفاد منه في باب الوصية. يُستفاد منه في باب الوصية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2270", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من هم أصحاب الفروض المحددة في القرآن؟", answer: "أصحاب الفروض المقدَّرة في القرآن: 1) الزوج: النصف أو الربع. 2) الزوجة/الزوجات: الربع أو الثمن. 3) الأم: الثلث أو السدس. 4) الأب: السدس (عصبة). 5) البنت/البنات: النصف أو الثلثان. 6) الأخت الشقيقة: النصف أو الثلثان. 7) الجدة: السدس. 8) الأخ لأم والأخت لأم: السدس أو الثلث.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2271", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من الذين يُحجَبون حجب حرمان من الميراث؟ اذكر أمثلة.", answer: "حجب الحرمان: حرمان الوارث من الإرث بسبب وجود وارث أقوى منه. أمثلة: 1) الجد يُحجَب بوجود الأب. 2) الإخوة يُحجَبون بوجود الابن أو الأب. 3) بنت الابن تُحجَب بوجود بنتين فأكثر إلا إذا وُجد معها ابن ابن. 4) الأخت لأم تُحجَب بوجود الفرع الوارث أو الأصل الذكر. والمانعون من الإرث: الكفر، والقتل العمد، والرق.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2272", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "شيء يزداد بالإنفاق منه في الخير، فما هو؟", answer: "الأجر — يزداد بالإنفاق في سبيل الله، فلا ينقص كما ينقص المال بالصرف.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2273", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "عبادة لا تصح إلا بدخول الوقت والطهارة واستقبال القبلة، فما هي؟", answer: "الصلاة — عبادة لا تصح إلا بدخول الوقت والطهارة واستقبال القبلة.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2274", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "شهر فيه ليلة خير من ألف شهر، فما هو؟", answer: "رمضان — الشهر الذي فيه ليلة القدر، وهي خير من ألف شهر كما في سورة القدر.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2275", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "كتاب لا يأتيه الباطل من بين يديه ولا من خلفه، فما هو؟", answer: "القرآن الكريم — كتاب الله المنزل على محمد ﷺ، لا يأتيه الباطل من بين يديه ولا من خلفه.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2276", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "بيت يطوف حوله المسلمون في الحج والعمرة، فما هو؟", answer: "الكعبة — البيت الحرام في مكة الذي يطوف حوله المسلمون في الحج والعمرة.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2277", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "عبادة تجمع أعمال البدن والمال والروح جميعاً، فما هي؟", answer: "الحج — عبادة تجمع أعمال البدن والمال والروح، وهي ركن من أركان الإسلام.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2278", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "ليلة يبحث عنها المسلمون في العشر الأواخر من رمضان، خير من ألف شهر، فما هي؟", answer: "ليلة القدر — الليلة التي يبحث عنها المسلمون في العشر الأواخر من رمضان.", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2279", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "شيء أخبر النبي ﷺ أنه لا ينقص بالإنفاق في سبيل الله، فما هو؟", answer: "المال؛ لقوله ﷺ: «ما نقصت صدقةٌ من مال» (أخرجه مسلم ٢٥٨٨ من حديث أبي هريرة)، فالصدقة لا تنقص المال بل يُخلف الله عليه بالبركة والأجر", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2280", section: "الألغاز الشرعية", category: "عام", level: "صعب", question: "ما الشيء الذي أخبر النبي ﷺ أنه أثقل ما يوضع في ميزان المؤمن؟", answer: "حسن الخُلُق؛ لقوله ﷺ: «ما من شيء أثقل في ميزان المؤمن يوم القيامة من خُلُق حسن» (أخرجه أبو داود ٤٧٩٩ والترمذي ٢٠٠٢ وقال: حسن صحيح، من حديث أبي الدرداء)", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2281", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "ما الكلمة التي أخبر النبي ﷺ أن من كان آخر كلامه من الدنيا دخل الجنة؟", answer: "«لا إله إلا الله»؛ لقوله ﷺ: «من كان آخر كلامه لا إله إلا الله دخل الجنة» (أخرجه أبو داود ٣١١٦ من حديث معاذ بن جبل رضي الله عنه، وحسّنه الألباني)", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2282", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "ما الصلاة التي تُعدل صلاة قيام نصف الليل؟", answer: "صلاة العشاء في جماعة؛ لقوله ﷺ: «من صلّى العشاء في جماعة فكأنما قام نصف الليل، ومن صلّى الصبح في جماعة فكأنما صلّى الليل كله» (أخرجه مسلم ٦٥٦ من حديث عثمان بن عفان رضي الله عنه)", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2283", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "أيُّ أيام السنة يكون صيامه كفارةً لسنتين؟", answer: "يوم عرفة (التاسع من ذي الحجة)؛ قال ﷺ في صيامه: «أحتسب على الله أن يُكفّر السنة التي قبله والسنة التي بعده» (أخرجه مسلم ١١٦٢ من حديث أبي قتادة، وفيه أن صيام عاشوراء يُكفّر السنة الماضية). والتكفير للصغائر، وصيام عرفة مستحب لغير الحاج، وأما الحاج بعرفة فالسنة له فطره كما في حديث أم الفضل (البخاري ١٩٨٨، مسلم ١١٢٣)", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2284", section: "الألغاز الشرعية", category: "عام", level: "سهل", question: "ما المدينة التي سُمِّيت «مدينة النبي» ﷺ، ووُعِد الصابر على شدّتها بشفاعته؟", answer: "المدينة النبوية (المنورة)، وكانت تُسمى قبل الهجرة يثرب؛ وفي فضلها قوله ﷺ: «لا يصبر على لأوائها وشدتها أحد إلا كنتُ له شفيعًا أو شهيدًا يوم القيامة» (أخرجه مسلم في كتاب الحج، باب الترغيب في سكنى المدينة والصبر على لأوائها)", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2285", section: "الألغاز الشرعية", category: "عام", level: "متوسط", question: "أيُّ الأنبياء ذكر الله مدة لبثه في قومه فبلغت ألف سنة إلا خمسين عامًا؟", answer: "نوح عليه السلام؛ قال تعالى: ﴿وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًۭا﴾ [العنكبوت: ١٤]. والمذكور في الآية هو مدة لبثه داعيًا في قومه لا مجموع عمره، فمجموع عمره لم يرد فيه نص قاطع وإنما هي أقوال للمفسرين", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2286", section: "الألغاز الشرعية", category: "عام", level: "صعب", question: "نبي أُمر بذبح ابنه ثم فداه الله بذبح عظيم، فمن هو؟", answer: "إبراهيم عليه السلام، أُمر بذبح ابنه في المنام ثم فداه الله؛ قال تعالى: ﴿وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍۢ﴾ [الصافات: ١٠٧]. والذبيح هو إسماعيل عليه السلام على قول جمهور المفسرين ورجّحه ابن كثير، وقيل هو إسحاق", explanation: "يُستفاد منه في باب عام. يُستفاد منه في باب عام مع الرجوع إلى مراجع سُنّة. الجواب يُختبر فهم الألغاز الشرعية لا الحفظ اللفظي فقط.", reference: "مراجع سُنّة" },
  { id: "2287", section: "الألغاز الشرعية", category: "ألغاز الطهارة", level: "صعب", question: "من هي التي تصلي الصلاة الواحدة مرتين؟", answer: "المرأة التي تطوف في المسجد الحرام فإنها تصلي ركعتي الطواف في وقت النهي (بعد العصر مثلاً) مرتين إذا أعادتها وقت الجواز", explanation: "يُستفاد منه في باب ألغاز الطهارة. يُستفاد منه في باب ألغاز الطهارة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2288", section: "الألغاز الشرعية", category: "ألغاز الصلاة", level: "صعب", question: "ما الصلاة التي لا قراءة فيها ولا ركوع ولا سجود ولا تشهد؟", answer: "صلاة الجنازة — وإن كانت دعاءً وتكبيراً وسلاماً. أو بعض العلماء يعدّ صلاة المأموم المسبوق في التكبيرات", explanation: "يُستفاد منه في باب ألغاز الصلاة. يُستفاد منه في باب ألغاز الصلاة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2289", section: "الألغاز الشرعية", category: "ألغاز الصيام", level: "متوسط", question: "من هو الذي يصوم بلا نية ويصح صومه؟", answer: "المسلم الذي نوى الصوم من المساء ثم نسي النية، وصيامه صحيح عند الجمهور لأن النية الضمنية قائمة بالتزام الصوم", explanation: "يُستفاد منه في باب ألغاز الصيام. يُستفاد منه في باب ألغاز الصيام مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2290", section: "الألغاز الشرعية", category: "ألغاز الزكاة", level: "صعب", question: "ما المال الذي تجب فيه الزكاة قبل حوله الحولي؟", answer: "الزروع والثمار — تجب فيها الزكاة عند حصادها لا بحلول حول. قال تعالى: وآتوا حقه يوم حصاده", explanation: "يُستفاد منه في باب ألغاز الزكاة. يُستفاد منه في باب ألغاز الزكاة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2291", section: "الألغاز الشرعية", category: "ألغاز متنوعة", level: "صعب", question: "ما العبادة التي يجوز أداؤها بغير وضوء ولا طهارة؟", answer: "الذكر والدعاء والتسبيح — لا يُشترط لها الطهارة وإن كانت أفضل. وكذلك الصلاة على النبي ﷺ وقراءة الكتب الشرعية", explanation: "يُستفاد منه في باب ألغاز متنوعة. يُستفاد منه في باب ألغاز متنوعة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2292", section: "الألغاز الشرعية", category: "ألغاز متنوعة", level: "متوسط", question: "من هو الشخص الذي صح نكاحه وليس بولي ولا شاهد ولا مهر مسمى؟", answer: "النبي ﷺ — أباح الله له الزواج بالهبة بلا مهر مسمى، وهو خصيصة له دون سائر المؤمنين كما أشارت الآية الكريمة", explanation: "يُستفاد منه في باب ألغاز متنوعة. يُستفاد منه في باب ألغاز متنوعة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2293", section: "الرقائق", category: "أخلاق المسلم", level: "سهل", question: "ما أعلى درجات اليقين التي ذكرها الله في القرآن؟", answer: "عين اليقين — ذكرت في سورة التكاثر. وحق اليقين — ذكرت في سورة الواقعة والحاقة. وعلم اليقين — في سورة التكاثر أيضاً.", explanation: "يُستفاد منه في باب أخلاق المسلم. يُستفاد منه في باب أخلاق المسلم مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2294", section: "الرقائق", category: "آداب الكلام", level: "سهل", question: "ما حكم كثرة الكلام بلا فائدة في الإسلام؟", answer: "مكروه ومنهي عنه — قال ﷺ: «من صمت نجا» وقال: «إن من حسن إسلام المرء تركه ما لا يعنيه» — رواه الترمذي.", explanation: "يُستفاد منه في باب آداب الكلام. يُستفاد منه في باب آداب الكلام مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2295", section: "الرقائق", category: "آداب المسجد", level: "سهل", question: "بأي رجل يُستحب الدخول للمسجد؟", answer: "بالرجل اليمنى — لحديث: «إذا دخل أحدكم المسجد فليبدأ بيمينه» ومثله الخروج يبدأ باليسرى.", explanation: "يُستفاد منه في باب آداب المسجد. يُستفاد منه في باب آداب المسجد مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2296", section: "الرقائق", category: "الأخلاق الذميمة", level: "متوسط", question: "ما أكبر الكبائر التي حذّر منها النبي ﷺ؟", answer: "سُئل ﷺ: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله، قال: «الإشراك بالله، وعقوق الوالدين» ثم جلس وقال: «ألا وقول الزور، وشهادة الزور» (متفق عليه — رواه البخاري ومسلم عن أبي بكرة)", explanation: "يُستفاد منه في باب الأخلاق الذميمة. يُستفاد منه في باب الأخلاق الذميمة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2297", section: "الرقائق", category: "الدعاء", level: "سهل", question: "ما الدعاء المأثور عند الاستيقاظ من النوم؟", answer: "«الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور» — رواه البخاري. أو: «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير» عشراً.", explanation: "يُستفاد منه في باب الدعاء. يُستفاد منه في باب الدعاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2298", section: "الرقائق", category: "الذكر والدعاء", level: "سهل", question: "بمَ أرشد النبي ﷺ فاطمة رضي الله عنها لمّا طلبت منه خادماً؟", answer: "قال لها ﷺ: «ألا أدلّك على ما هو خير لك من خادم؟ تسبّحين ثلاثاً وثلاثين، وتحمدين ثلاثاً وثلاثين، وتكبّرين أربعاً وثلاثين حين تأخذين مضجعك» (متفق عليه — رواه البخاري 3705 ومسلم 2727 عن علي بن أبي طالب).", explanation: "يُستفاد منه في باب الذكر والدعاء. يُستفاد منه في باب الذكر والدعاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2299", section: "الرقائق", category: "التوبة والاستغفار", level: "سهل", question: "ما أفضل صيغة للاستغفار وما تسمى؟", answer: "تسمى سيد الاستغفار: «اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شر ما صنعت، أبوء لك بنعمتك عليّ وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت».", explanation: "يُستفاد منه في باب التوبة والاستغفار. يُستفاد منه في باب التوبة والاستغفار مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2300", section: "الرقائق", category: "التوبة والاستغفار", level: "سهل", question: "ما شروط التوبة الصحيحة من الذنب؟", answer: "ثلاثة شروط: 1- الإقلاع عن الذنب فوراً. 2- الندم على ما فات. 3- العزم على عدم العودة. وإن كان الذنب يتعلق بحق آدمي زُيد شرط رابع: رد الحقوق أو الاستحلال من أصحابها.", explanation: "يُستفاد منه في باب التوبة والاستغفار. يُستفاد منه في باب التوبة والاستغفار مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2301", section: "الرقائق", category: "التزكية", level: "سهل", question: "ما آفة اللسان التي حذّر منها النبي ﷺ حين سُئل عن أكثر ما يُدخل النار؟", answer: "الفم والفرج — قال ﷺ: «أكثر ما يُدخل الناسَ النار الأجوفان: الفم والفرج» (الترمذي ٢٠٠٤، صححه الألباني). واللسان مفتاح الفم ومدخل أعظم الذنوب.", explanation: "يُستفاد منه في باب التزكية. يُستفاد منه في باب التزكية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2302", section: "الرقائق", category: "الزهد", level: "متوسط", question: "عرّف الزهد في الدنيا وما الفرق بينه وبين الفقر؟", answer: "الزهد: ترك ما لا ينفع في الآخرة وإيثار ما فيه رضا الله. وهو حال القلب لا المال؛ فقد كان سليمان ﷺ ذا ملك عظيم وهو زاهد، وقد يكون الفقير حريصاً غير زاهد.", explanation: "يُستفاد منه في باب الزهد. يُستفاد منه في باب الزهد مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2303", section: "الرقائق", category: "أمراض القلوب", level: "متوسط", question: "ما الكبر وما ضابطه عند أهل العلم؟", answer: "قال ﷺ: «الكبر: بطَر الحق وغمط الناس» (رواه مسلم). بطر الحق: رد الحق وعدم قبوله. غمط الناس: احتقارهم. وهو من الكبائر المهلكة للقلب.", explanation: "يُستفاد منه في باب أمراض القلوب. يُستفاد منه في باب أمراض القلوب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2304", section: "الرقائق", category: "التوبة", level: "سهل", question: "ما أفضل وقت للاستغفار وما دليله من السنة؟", answer: "وقت الأسحار قُبيل الفجر — قال الله تعالى: ﴿وَالْمُسْتَغْفِرِينَ بِالْأَسْحَارِ﴾ (آل عمران: 17). وثبت في السنة نزول الرب تبارك وتعالى في كل ليلة إلى السماء الدنيا في الثلث الأخير.", explanation: "يُستفاد منه في باب التوبة. يُستفاد منه في باب التوبة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2305", section: "الرقائق", category: "اليقين", level: "صعب", question: "ما الفرق بين الوسواس القهري الطبي وبين وسواس الشيطان الشرعي؟", answer: "وسواس الشيطان: خاطر إثمي عارض يُقاومه العبد بالذكر والاستعاذة ولا حرج فيه. والوسواس القهري الطبي: حالة مرضية تستدعي العلاج الطبي. وحكمهما يختلف: الأول مُمانَع شرعاً، والثاني مُعالَج طباً.", explanation: "يُستفاد منه في باب اليقين. يُستفاد منه في باب اليقين مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2306", section: "الرقائق", category: "التفكر", level: "سهل", question: "ما الساعات التي يُستحب فيها التفكر والتأمل في خلق الله؟", answer: "خير أوقاته بعد صلاة الفجر قبل شروق الشمس، وفي الليل. فقد نزلت عليه ﷺ ذات ليلة آيات ختام سورة آل عمران (في خلق السماوات والأرض واختلاف الليل والنهار) وقال: «لقد أُنزلت عليّ الليلة آيات، ويل لمن قرأها ولم يتفكر فيها» (رواه ابن حبان في صحيحه بإسناد صحيح على شرط مسلم).", explanation: "يُستفاد منه في باب التفكر. يُستفاد منه في باب التفكر مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2307", section: "الرقائق", category: "ذكر الموت", level: "متوسط", question: "ما الحديث الوارد في فضل ذكر الموت وكثرته؟", answer: "قال ﷺ: «أكثروا ذكر هاذم اللذات: الموت» (رواه الترمذي والنسائي، صحيح). والمعنى: قاطع اللذات وهادمها لأنه يُذكّر بزوال النعيم.", explanation: "يُستفاد منه في باب ذكر الموت. يُستفاد منه في باب ذكر الموت مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2308", section: "الرقائق", category: "الخوف والرجاء", level: "متوسط", question: "هل يجوز اليأس من رحمة الله؟ ما حكمه؟", answer: "اليأس من رحمة الله كبيرة من الكبائر — قال الله تعالى: ﴿إِنَّهُ لَا يَيْأَسُ مِن رَّوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ﴾ (يوسف: 87). فاليأس من سمات الكافرين، والمؤمن يجمع الخوف والرجاء.", explanation: "يُستفاد منه في باب الخوف والرجاء. يُستفاد منه في باب الخوف والرجاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2309", section: "الرقائق", category: "المحبة والشوق", level: "سهل", question: "ما علامة محبة الله في قلب العبد؟", answer: "من علاماتها: 1- محبة النبي ﷺ واتباعه. 2- كثرة ذكر الله. 3- إيثار ما يُحب الله على ما يشتهي النفس. 4- الشوق إلى لقاء الله. قال ﷺ: «من أحب لقاء الله أحب الله لقاءه» (البخاري).", explanation: "يُستفاد منه في باب المحبة والشوق. يُستفاد منه في باب المحبة والشوق مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2310", section: "الرقائق", category: "العبودية", level: "صعب", question: "ما مقام العبودية ولماذا وصف الله نبيه ﷺ بالعبودية في أشرف مقاماته؟", answer: "العبودية لله هي أشرف مقامات الإنسان لأنها غاية الخلق. وصف الله نبيه بالعبد في ثلاثة مقامات عظيمة: الإسراء ﴿سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ﴾، والتحدي ﴿فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِ﴾، والدعوة ﴿وَأَنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ﴾.", explanation: "يُستفاد منه في باب العبودية. يُستفاد منه في باب العبودية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2311", section: "الرقائق", category: "التوبة والاستغفار", level: "سهل", question: "ما شروط التوبة النصوح؟", answer: "شروط التوبة النصوح ثلاثة: 1) الإقلاع عن الذنب فوراً. 2) الندم على ما مضى. 3) العزم على عدم العودة إليه أبداً. وإن كان الذنب يتعلق بحق آدمي يُضاف شرط رابع: رد الحق أو الاستحلال من صاحبه. قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَّصُوحًا﴾ (التحريم: 8).", explanation: "يُستفاد منه في باب التوبة والاستغفار. يُستفاد منه في باب التوبة والاستغفار مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2312", section: "الرقائق", category: "الورع والتقوى", level: "متوسط", question: "ما الفرق بين الورع والتقوى؟", answer: "التقوى: اتقاء سخط الله بفعل أوامره وترك نواهيه — وهي أعم. الورع: ترك ما يُشكل حله مخافة الوقوع في الحرام — وهو أخص. قال ابن القيم: «التقوى جماع الدين، والورع هو تركك ما تخشى ضرره في الآخرة». ومن أمثلته: ترك شبهات المعاملات خوف الربا، وترك ما لا يُعلم مصدره. قال ﷺ: «فمن اتقى الشبهات استبرأ لدينه وعرضه» (متفق عليه).", explanation: "يُستفاد منه في باب الورع والتقوى. يُستفاد منه في باب الورع والتقوى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2313", section: "الرقائق", category: "المراقبة والمحاسبة", level: "متوسط", question: "ما المقصود بمحاسبة النفس؟ وكيف يُطبَّق عملياً؟", answer: "محاسبة النفس: أن يقف العبد مع نفسه يومياً فيسألها عن ما فعلت وما تركت. قال عمر بن الخطاب: «حاسبوا أنفسكم قبل أن تُحاسَبوا». تطبيقه عملياً: 1) المراجعة المسائية: ما فعلت اليوم من خير أو شر؟ 2) معاهدة النفس على الإصلاح قبل النوم. 3) التوبة فور الوقوع. 4) تفقد الصلاة والذكر والمعاملة مع الناس.", explanation: "يُستفاد منه في باب المراقبة والمحاسبة. يُستفاد منه في باب المراقبة والمحاسبة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2314", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما أركان الحج؟", answer: "الإحرام والوقوف بعرفة وطواف الإفاضة والسعي بين الصفا والمروة", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" }
];

